package com.mamtrex.hospital.bloodbank;
import com.mamtrex.hospital.audit.AuditService; import com.mamtrex.hospital.shared.NotFoundException; import jakarta.validation.Valid; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/blood-units") public class BloodUnitController { private final BloodUnitRepository repo; private final AuditService audit; public BloodUnitController(BloodUnitRepository r,AuditService a){repo=r;audit=a;} public record Request(@jakarta.validation.constraints.NotBlank String unitCode, @jakarta.validation.constraints.NotBlank String bloodType, @jakarta.validation.constraints.NotBlank String component, @jakarta.validation.constraints.NotBlank String expiresOn, @jakarta.validation.constraints.NotBlank String status){} @PostMapping public BloodUnit create(@Valid @RequestBody Request r){var e=repo.save(new BloodUnit(r.unitCode(), r.bloodType(), r.component(), r.expiresOn(), r.status()));audit.record("CREATE","BloodUnit",e.getId().toString(),"created");return e;} @GetMapping public List<BloodUnit> list(){return repo.findAll();} @GetMapping("/{id}") public BloodUnit get(@PathVariable UUID id){return repo.findById(id).orElseThrow(()->new NotFoundException("BloodUnit not found: "+id));} @DeleteMapping("/{id}") public void delete(@PathVariable UUID id){if(!repo.existsById(id))throw new NotFoundException("BloodUnit not found: "+id);repo.deleteById(id);audit.record("DELETE","BloodUnit",id.toString(),"deleted");} }
